surface.AgentRole:
export interface AgentRole {
    description: string;
    model?: string;
    name: string;
    prompt: string;
    thinkingLevel?: ThinkingLevel;
}

surface.AgentRoleProblem:
export interface AgentRoleProblem {
    file: string;
    reason: string;
}

surface.AgentRoles:
export interface AgentRoles {
    problems: AgentRoleProblem[];
    roles: AgentRole[];
}

surface.ApnsPushToken:
export interface ApnsPushToken {
    apns: string;
    environment: ApnsEnvironment;
}

surface.CallMethods:
export interface CallMethods {
    abort: {
        args: {
            conversationId: ConversationId;
        };
        result: null;
    };
    addProject: {
        args: {
            path: string;
        };
        result: Project;
    };
    answer: {
        args: {
            answers: QuestionAnswer[];
            conversationId: ConversationId;
            kind: string;
            requestId: string;
        };
        result: {
            first: boolean;
        };
    };
    archive: {
        args: {
            archived: boolean;
            conversationId: ConversationId;
        };
        result: null;
    };
    changes: {
        args: {
            conversationId: ConversationId;
        };
        result: {
            available: false;
            branch?: string;
            reason: string;
        } | {
            available: true;
            base: string;
            branch?: string;
            patch: string;
            truncated: boolean;
        };
    };
    compact: {
        args: {
            conversationId: ConversationId;
            instructions?: string;
        };
        result: {
            taskId: string;
        };
    };
    createAgent: {
        args: {
            role: AgentRole;
        };
        result: null;
    };
    createConversation: {
        args: {
            agent?: string;
            checkout?: "project" | "worktree";
            home: Home;
            images?: MessageImage[];
            model?: ModelRef;
            requestId: string;
            text: string;
            thinkingLevel?: ThinkingLevel;
        };
        result: {
            conversationId: ConversationId;
        };
    };
    createPairing: {
        args: Record<string, never>;
        result: {
            expiresAt: number;
            url: string;
        };
    };
    deleteAgent: {
        args: {
            name: string;
        };
        result: null;
    };
    fork: {
        args: {
            conversationId: ConversationId;
            entryId: string;
            removeTools?: string[];
        };
        result: {
            conversationId: ConversationId;
        };
    };
    listFiles: {
        args: {
            query: string;
            scope: FileScope;
        };
        result: FileListing;
    };
    listFolders: {
        args: {
            path?: string;
        };
        result: FolderListing;
    };
    listSkills: {
        args: {
            scope: SkillScope;
        };
        result: SkillListing;
    };
    logout: {
        args: {
            providerId: string;
        };
        result: null;
    };
    removeProject: {
        args: {
            path: string;
        };
        result: null;
    };
    renameConversation: {
        args: {
            conversationId: ConversationId;
            title: string;
        };
        result: null;
    };
    revokeDevice: {
        args: {
            publicKey: string;
        };
        result: null;
    };
    setModel: {
        args: {
            conversationId: ConversationId;
            model: ModelRef;
        };
        result: null;
    };
    setPushToken: {
        args: {
            token: PushToken | null;
        };
        result: null;
    };
    setThinkingLevel: {
        args: {
            conversationId: ConversationId;
            level: ThinkingLevel;
        };
        result: null;
    };
    steerQueued: {
        args: {
            conversationId: ConversationId;
            submissionId: number;
        };
        result: {
            outcome: "sent" | "steered" | "unavailable";
        };
    };
    submit: {
        args: {
            conversationId: ConversationId;
            images?: MessageImage[];
            requestId: string;
            text: string;
            whenBusy: "followUp" | "steer";
        };
        result: {
            submissionId: number;
        };
    };
    updateAgent: {
        args: {
            role: AgentRole;
        };
        result: null;
    };
    updateSettings: {
        args: {
            patch: HostSettingsPatch;
        };
        result: null;
    };
    withdrawQueued: {
        args: {
            conversationId: ConversationId;
            submissionId: number;
        };
        result: {
            outcome: "sent" | "withdrawn";
        };
    };
}

surface.ClientFrame:
export type ClientFrame = {
    [M in CallMethod]: {
        args: CallMethods[M]["args"];
        id: number;
        method: M;
        type: "call";
    };
}[CallMethod] | {
    stream: StreamName;
    type: "subscribe";
} | {
    stream: StreamName;
    type: "unsubscribe";
};

surface.CodemodeCallSchema:
export const CodemodeCallSchema = Type.Object({
    args: Type.String(),
    details: Type.Optional(Type.Unknown()),
    durationMs: Type.Optional(Type.Number()),
    error: Type.Optional(Type.String()),
    id: Type.Optional(Type.Number()),
    name: Type.String(),
    status: Type.Union([Type.Literal("cancelled"), Type.Literal("error"), Type.Literal("ok"), Type.Literal("running")]),
});

surface.ConversationDefaults:
export interface ConversationDefaults {
    model?: ModelRef;
    thinkingLevel?: ThinkingLevel;
}

surface.ConversationSummary:
export interface ConversationSummary {
    activity?: {
        target?: string;
        tool: string;
    };
    forkedAt?: string;
    id: ConversationId;
    kind: "conversation" | "fork" | "subagent";
    label?: string;
    parent?: ConversationId;
    role?: string;
    status?: "failed" | "needs-answer" | "running";
    title?: string;
    updatedAt?: number;
}

surface.DeviceEntry:
export type DeviceEntry = {
    name: string;
    pairedAt: number;
    publicKey: string;
    source?: DeviceSource;
};

surface.FileListing:
export interface FileListing {
    files: string[];
    truncated: boolean;
}

surface.FileScope:
export type FileScope = {
    conversationId: ConversationId;
    kind: "conversation";
} | {
    checkout: "project" | "worktree";
    kind: "project";
    path: string;
};

surface.FolderListing:
export interface FolderListing {
    folders: {
        name: string;
        path: string;
    }[];
    home: string;
    path: string;
}

surface.Home:
export type Home = {
    kind: "chat";
} | {
    kind: "project";
    path: string;
};

surface.HostIndex:
export type HostIndex = {
    checkouts?: WorktreeCheckout[];
    conversations: IndexEntry[];
    projects: Project[];
};

surface.HostSettings:
export interface HostSettings {
    acceptAccountDevices: boolean;
    custom: HostSettingKey[];
    defaultModel: ModelRef | null;
    defaultThinkingLevel: ThinkingLevel | null;
    followUpMode: QueueMode;
    hostName?: string;
    steeringMode: QueueMode;
}

surface.HostSettingsPatch:
export type HostSettingsPatch = {
    [K in HostSettingKey]?: Exclude<HostSettings[K], null> | null;
};

surface.HostStreamValues:
export interface HostStreamValues {
    agents: AgentRoles;
    auth: HostAuth;
    conversations: ConversationSummary[];
    devices: HostDevices;
    index: HostIndex;
    mcp: McpStatus | null;
    models: ModelSummary[];
    settings: HostSettings;
}

surface.IndexEntry:
export type IndexEntry = {
    archived?: boolean;
    createdAt: number;
    home: Home;
    id: ConversationId;
    requestId?: string;
    role?: string;
};

surface.McpServerStatus:
export interface McpServerStatus {
    error?: string;
    name: string;
    state: "connected" | "connecting" | "disabled" | "failed";
    tools: number;
}

surface.McpStatus:
export interface McpStatus {
    configPath: string;
    errors: string[];
    servers: McpServerStatus[];
}

surface.MessageImage:
export type MessageImage = {
    data: string;
    mimeType: ImageMimeType;
};

surface.ModelSummary:
export interface ModelSummary extends ModelRef {
    contextWindow: number;
    images?: boolean;
    name: string;
    thinkingLevels: ThinkingLevel[];
}

surface.Notice:
export interface Notice {
    id: number;
    level: "error" | "info" | "warning";
    message: string;
}

surface.Project:
export type Project = {
    addedAt: number;
    name: string;
    path: string;
};

surface.ProtocolVersion:
export interface ProtocolVersion {
    major: number;
    minor: number;
}

surface.QuestionAnswerSchema:
export const QuestionAnswerSchema = Type.Object({
    other: Type.Optional(Type.String()),
    selected: Type.Array(Type.String()),
});

surface.QuestionItemSchema:
export const QuestionItemSchema = Type.Object({
    header: Type.String({ maxLength: 16, minLength: 1 }),
    multiSelect: Type.Optional(Type.Boolean()),
    options: Type.Array(QuestionOptionSchema, { maxItems: 4, minItems: 2 }),
    question: Type.String({ minLength: 1 }),
});

surface.QuestionOptionSchema:
export const QuestionOptionSchema = Type.Object({
    description: Type.Optional(Type.String()),
    label: Type.String({ minLength: 1 }),
});

surface.QuestionRequestSchema:
export const QuestionRequestSchema = Type.Object({
    askedAt: Type.Number(),
    id: Type.String({ minLength: 1 }),
    questions: Type.Array(QuestionItemSchema, { maxItems: 4, minItems: 1 }),
    resolution: Type.Optional(QuestionResolutionSchema),
});

surface.QuestionResolutionSchema:
export const QuestionResolutionSchema = Type.Union([
    Type.Object({ answers: Type.Array(QuestionAnswerSchema), at: Type.Number(), outcome: Type.Literal("answered") }),
    Type.Object({ at: Type.Number(), outcome: Type.Literal("cancelled") }),
    Type.Object({ at: Type.Number(), outcome: Type.Literal("dismissed") }),
]);

surface.ServerFrame:
export type ServerFrame = {
    defaults?: ConversationDefaults;
    docs: {
        kind: string;
        presentation?: PresentationType;
    }[];
    hostVersion?: string;
    models: ModelSummary[];
    protocol: ProtocolVersion;
    session: SessionInfo;
    toolPresentations: Record<string, PresentationType>;
    type: "hello";
} | {
    reason: string;
    stream: StreamName;
    type: "ended";
} | {
    level: Notice["level"];
    message: string;
    type: "notice";
} | {
    ops: Op[];
    stream: StreamName;
    type: "ops";
} | {
    error: string;
    id: number;
    ok: false;
    type: "result";
} | {
    id: number;
    ok: true;
    type: "result";
    value: unknown;
} | {
    stream: StreamName;
    type: "snapshot";
    value: unknown;
};

surface.SessionInfo:
export interface SessionInfo {
    directory: string;
    id: string;
}

surface.SkillListing:
export interface SkillListing {
    skills: {
        description: string;
        name: string;
        source: "project" | "user";
    }[];
}

surface.SkillScope:
export type SkillScope = {
    kind: "chat";
} | {
    conversationId: ConversationId;
    kind: "conversation";
} | {
    checkout: "project" | "worktree";
    kind: "project";
    path: string;
};

surface.StoredLogin:
export interface StoredLogin {
    kind: "api_key" | "oauth";
    name: string;
    providerId: string;
    subscription: boolean;
}

surface.TodoItemSchema:
export const TodoItemSchema = Type.Object({
    status: Type.Union([Type.Literal("completed"), Type.Literal("in_progress"), Type.Literal("pending")]),
    text: Type.String({ minLength: 1 }),
});

surface.WorktreeCheckout:
export type WorktreeCheckout = {
    base: string;
    branch: string;
    conversationId: ConversationId;
    path: string;
    repo: string;
    snapshot?: string;
    subdir: string;
};
